 public final class ZipUtils {

     private ZipUtils() {}

+    private static Path resolveZipEntry(Path targetDir, String entryName) throws IOException {
+        // Defend against Zip Slip (CWE-22): normalize and ensure the result stays within targetDir.
+        Path normalizedTargetDir = targetDir.toAbsolutePath().normalize();
+        Path resolved = normalizedTargetDir.resolve(entryName).normalize();
+        if (!resolved.startsWith(normalizedTargetDir)) {
+            throw new IOException("Blocked zip entry with illegal path: " + entryName);
+        }
+        return resolved;
+    }
