+    private static void rejectSymlinkTraversal(Path targetDir, Path outputPath) throws IOException {
+        // Prevent writing through symlinks that may escape targetDir.
+        Path normalizedTargetDir = targetDir.toAbsolutePath().normalize();
+        Path parent = outputPath.toAbsolutePath().normalize().getParent();
+        if (parent == null) {
+            parent = normalizedTargetDir;
+        }
+        if (!parent.startsWith(normalizedTargetDir)) {
+            throw new IOException("Blocked zip entry writing outside target directory: " + outputPath);
+        }
+
+        Path relative = normalizedTargetDir.relativize(parent);
+        Path current = normalizedTargetDir;
+        for (Path part : relative) {
+            current = current.resolve(part);
+            if (Files.exists(current, LinkOption.NOFOLLOW_LINKS) && Files.isSymbolicLink(current)) {
+                throw new IOException("Blocked zip extraction through symlink: " + current);
+            }
+        }
+    }
+
     public static void unzip(InputStream is, Path targetDir) throws IOException {
         Files.createDirectories(targetDir);
         try (ZipInputStream zis = new ZipInputStream(new BufferedInputStream(is))) {
             ZipEntry entry;
             while ((entry = zis.getNextEntry()) != null) {
-                Path filePath = targetDir.resolve(entry.getName());
-                if (entry.isDirectory()) {
-                    Files.createDirectories(filePath);
-                } else {
-                    Files.createDirectories(filePath.getParent());
-                    Files.copy(zis, filePath, StandardCopyOption.REPLACE_EXISTING);
-                }
+                Path filePath = resolveZipEntry(targetDir, entry.getName());
+                rejectSymlinkTraversal(targetDir, filePath);
+                if (entry.isDirectory()) {
+                    Files.createDirectories(filePath);
+                } else {
+                    Path parent = filePath.getParent();
+                    if (parent != null) {
+                        Files.createDirectories(parent);
+                    }
+                    Files.copy(zis, filePath, StandardCopyOption.REPLACE_EXISTING);
